INSERT INTO homepage_sections (id, section_key, section_type, title, subtitle, content, image, video, link_text, link_url, product_source, product_filter, max_products, display_order, is_active, metadata, updated_at) VALUES (1, 'hero', 'hero', 'The Art of Handwoven Rugs', 'Curated masterpieces woven with tradition, designed for modern living', NULL, 'https://images.unsplash.com/photo-1600121848594-d8644e57abab?auto=format&fit=crop&w=1800&q=85', NULL, 'EXPLORE COLLECTION', '/shop', NULL, NULL, NULL, 1, 1, NULL, '2026-09-18 14:29:23');
INSERT INTO homepage_sections (id, section_key, section_type, title, subtitle, content, image, video, link_text, link_url, product_source, product_filter, max_products, display_order, is_active, metadata, updated_at) VALUES (2, 'collections_grid', 'collections', 'OUR COLLECTION', 'Discover our two core heritage disciplines: Handcrafted Carpets and Egyptian Kilims', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, 1, NULL, '2026-09-18 14:29:23');
INSERT INTO homepage_sections (id, section_key, section_type, title, subtitle, content, image, video, link_text, link_url, product_source, product_filter, max_products, display_order, is_active, metadata, updated_at) VALUES (3, 'best_sellers', 'products', 'Best Sellers', 'Our most loved handwoven pieces', NULL, NULL, NULL, 'SEE ALL', '/shop?sort=best_seller', 'best_seller', NULL, 10, 3, 1, NULL, '2026-09-18 14:29:23');
INSERT INTO homepage_sections (id, section_key, section_type, title, subtitle, content, image, video, link_text, link_url, product_source, product_filter, max_products, display_order, is_active, metadata, updated_at) VALUES (4, 'featured_products', 'products', 'Featured', 'Hand-picked by our curators', NULL, NULL, NULL, 'SEE ALL', '/shop?filter=featured', 'featured', NULL, 10, 4, 1, NULL, '2026-09-18 14:29:23');
INSERT INTO homepage_sections (id, section_key, section_type, title, subtitle, content, image, video, link_text, link_url, product_source, product_filter, max_products, display_order, is_active, metadata, updated_at) VALUES (5, 'brand_story', 'story', 'The Story Behind Egyptian Kilims', '100% Handwoven Artistry', 'Egyptian kilims are part of a rich tradition of handcraftsmanship rooted in Egyptian culture and heritage. Every Yadawy piece is 100% handwoven by Egyptian artisans using traditional techniques passed down through generations. Made with high-quality Egyptian wool on a durable cotton foundation, each unique piece is built to last for decades.', 'https://images.unsplash.com/photo-1579656381226-5fc0f0100c3b?auto=format&fit=crop&w=1200&q=80', NULL, 'EXPLORE OUR STORY', '/about', NULL, NULL, NULL, 5, 1, NULL, '2026-09-18 14:29:23');
INSERT INTO homepage_sections (id, section_key, section_type, title, subtitle, content, image, video, link_text, link_url, product_source, product_filter, max_products, display_order, is_active, metadata, updated_at) VALUES (6, 'new_arrivals', 'products', 'New Arrivals', 'Fresh additions to our collection', NULL, NULL, NULL, 'SEE ALL', '/shop?sort=newest', 'new_arrival', NULL, 10, 6, 1, NULL, '2026-09-18 14:29:23');
